using System.Reflection;
using GameLauncherGUI;
using Newtonsoft.Json.Linq;

internal static class GameCareChecks
{
    internal static void Run(bool ui)
    {
        int count=0;void Check(bool condition,string message){if(!condition)throw new Exception(message);count++;}
        void Reject(Action action){try{action();}catch(Exception ex)when(ex is IOException or InvalidDataException or ArgumentException or OperationCanceledException){count++;return;}throw new Exception("Unsafe game care action accepted");}
        string folder=Path.Combine(Path.GetTempPath(),"PlaySpaceCareChecks-"+Guid.NewGuid().ToString("N"));string data=Path.Combine(folder,"launcher"),saves=Path.Combine(folder,"saves");Directory.CreateDirectory(saves);Directory.CreateDirectory(Path.Combine(saves,"nested"));File.WriteAllText(Path.Combine(saves,"save.dat"),"one");File.WriteAllText(Path.Combine(saves,"nested","config.json"),"v1");
        var options=new GameCareOptions{SaveDirectory=saves,Notes="My local notes"};bool running=false;var store=new GameBackupStore(options,data,()=>running);var first=store.Create();Check(first.Files.Count==2&&first.Files.All(f=>f.Sha256.Length==64),"Snapshot incomplete");Check(store.Verify(first.Id).Id==first.Id,"Valid snapshot rejected");Check(store.List().Count==1,"Snapshot listing failed");
        File.WriteAllText(Path.Combine(saves,"save.dat"),"two");File.WriteAllText(Path.Combine(saves,"nested","config.json"),"v2");File.WriteAllText(Path.Combine(saves,"extra.dat"),"newer data");
        var plan=store.Preview(first.Id);Check(plan.Count(p=>p.Action=="Заменить")==2,"Restore preview didn't show changes");Check(store.Restore(first.Id)==2,"Restore count wrong");Check(File.ReadAllText(Path.Combine(saves,"save.dat"))=="one"&&File.ReadAllText(Path.Combine(saves,"extra.dat"))=="newer data","Restore lost current extra files or failed");
        var safety=store.List().Single(p=>p.Kind=="Перед восстановлением");Check(File.ReadAllText(Path.Combine(store.Folder,safety.Id,"files","save.dat"))=="two","Safety copy lost pre-restore contents");Check(store.Restore(first.Id)==0&&store.List().Count==2,"No-op restore created unnecessary copies");
        File.WriteAllText(Path.Combine(saves,"save.dat"),"rollback-original");File.WriteAllText(Path.Combine(saves,"nested","config.json"),"rollback-config");Reject(()=>store.Restore(first.Id,afterWrite:n=>throw new IOException("Fixture write failure")));Check(File.ReadAllText(Path.Combine(saves,"save.dat"))=="rollback-original"&&File.ReadAllText(Path.Combine(saves,"nested","config.json"))=="rollback-config","Failed restore didn't roll back");
        running=true;Reject(()=>store.Create());Reject(()=>store.Restore(first.Id));running=false;
        int points=store.List().Count;using(var cancellation=new CancellationTokenSource()){cancellation.Cancel();Reject(()=>store.Create(cancellation:cancellation.Token));Reject(()=>store.Restore(first.Id,cancellation.Token));}Check(store.List().Count==points,"Cancellation changed snapshots");
        string snapshotFile=Path.Combine(store.Folder,first.Id,"snapshot.json"),originalManifest=File.ReadAllText(snapshotFile);var manifest=JObject.Parse(originalManifest);manifest["Files"]![0]!["Path"]="../../outside.dat";File.WriteAllText(snapshotFile,manifest.ToString());Reject(()=>store.Verify(first.Id));Check(!File.Exists(Path.Combine(folder,"outside.dat")),"Snapshot traversal escaped root");File.WriteAllText(snapshotFile,originalManifest);
        manifest=JObject.Parse(originalManifest);manifest["Owner"]=Guid.NewGuid().ToString("N");File.WriteAllText(snapshotFile,manifest.ToString());Reject(()=>store.Verify(first.Id));File.WriteAllText(snapshotFile,originalManifest);
        manifest=JObject.Parse(originalManifest);manifest["Files"]![0]!["Path"]=".. /outside.dat";File.WriteAllText(snapshotFile,manifest.ToString());Reject(()=>store.Verify(first.Id));File.WriteAllText(snapshotFile,originalManifest);
        manifest=JObject.Parse(originalManifest);var duplicate=manifest["Files"]!.AsEnumerable().First(f=>f!["Path"]!.Value<string>()!.Contains('/'))!.DeepClone();duplicate["Path"]=duplicate["Path"]!.Value<string>()!.Replace('/','\\');((JArray)manifest["Files"]!).Add(duplicate);File.WriteAllText(snapshotFile,manifest.ToString());Reject(()=>store.Verify(first.Id));File.WriteAllText(snapshotFile,originalManifest);
        string firstPayload=Path.Combine(store.Folder,first.Id,"files","save.dat");File.WriteAllText(firstPayload,"corrupted");Reject(()=>store.Verify(first.Id));points=store.List().Count;Reject(()=>store.Restore(first.Id));Check(store.List().Count==points&&File.ReadAllText(Path.Combine(saves,"save.dat"))=="rollback-original","Damaged backup modified source");File.WriteAllText(firstPayload,"one");
        Reject(()=>store.Verify("../../outside"));options.SaveDirectory=Path.GetPathRoot(folder)!;Reject(()=>store.Source());options.SaveDirectory=data;Reject(()=>store.Source());options.SaveDirectory=store.Folder;Reject(()=>store.Source());options.SaveDirectory=saves;
        File.WriteAllText(Path.Combine(saves,"setup.exe"),"must not copy executable");Reject(()=>store.Create());File.Delete(Path.Combine(saves,"setup.exe"));Check(!Directory.EnumerateDirectories(store.Folder,".stage-*").Any(),"Failed snapshot left staging data");
        using(var guard=new FileStream(Path.Combine(store.Folder,"backup.lock"),FileMode.Open,FileAccess.ReadWrite,FileShare.None))Reject(()=>store.Create());
        string exe=Path.Combine(folder,"game.exe");File.WriteAllText(exe,"fixture-not-executable");var game=new GameInfo{Name="Demo Game",ExePath=exe,SteamAppId="",Care=options};
        Check(!GameReadiness.Inspect(game,()=>false,data).Any(c=>c.Blocking),"Existing local game blocked");Check(GameReadiness.Inspect(game,()=>true,data).Any(c=>c.Blocking),"Running game not blocked");game.ExePath=Path.Combine(folder,"missing.exe");Check(GameReadiness.Inspect(game,()=>false,data).Any(c=>c.Blocking),"Missing executable not blocked");game.ExePath=exe;game.SteamAppId="not-an-id";Check(GameReadiness.Inspect(game,()=>false,data).Any(c=>c.Blocking),"Invalid Steam ID accepted");game.SteamAppId="620";Check(!GameReadiness.Inspect(game,()=>false,data).Any(c=>c.Blocking),"Steam launch blocked unnecessarily");game.SteamAppId="";
        Check(GameReadiness.Arguments("-name \"Игрок 1\" -safe").SequenceEqual(new[]{"-name","Игрок 1","-safe"}),"Quoted launch arguments corrupted");Reject(()=>GameReadiness.Arguments("-a\n-b"));Reject(()=>GameReadiness.Arguments(new string('x',4097)));
        var preferences=new LauncherPreferences{HideWhilePlaying=true,RestoreAfterPlaying=false,NotificationsEnabled=false};preferences.Save(data);var loaded=LauncherPreferences.Load(data).Copy();Check(loaded.HideWhilePlaying&&!loaded.RestoreAfterPlaying&&!loaded.NotificationsEnabled,"Game mode preferences lost other settings");
        var mode=new GameModeState();mode.Arm("a");Check(!mode.Observe(Array.Empty<string>(),new[]{"a"}),"Launcher restored before game startup");Check(!mode.Observe(new[]{"a"},new[]{"a"}),"Launcher restored during game");Check(mode.Observe(Array.Empty<string>(),Array.Empty<string>())&&!mode.Observe(Array.Empty<string>(),Array.Empty<string>()),"Game exit restoration not one-shot");mode.Arm("a");mode.Arm("b");Check(!mode.Observe(new[]{"a"},new[]{"a","b"})&&!mode.Observe(new[]{"b"},new[]{"b"}),"Multiple games restored too early");Check(mode.Observe(Array.Empty<string>(),Array.Empty<string>()),"Last game exit didn't restore launcher");mode.Arm("timeout");Check(mode.Observe(Array.Empty<string>(),Array.Empty<string>()),"Failed launch timeout didn't restore launcher");
        string library=Path.Combine(data,"games.json");game.LaunchArguments="-safe";GameLibraryStore.Save(library,new(){game});var roundTrip=GameLibraryStore.Load(library).Games.Single();Check(roundTrip.Care?.Id==options.Id&&roundTrip.Care.Notes==options.Notes&&roundTrip.LaunchArguments=="-safe","Game care library round trip failed");
        if(ui){
            var flags=BindingFlags.Instance|BindingFlags.NonPublic;void Pump(Func<bool> done){var end=DateTime.UtcNow.AddSeconds(5);while(!done()&&DateTime.UtcNow<end){Application.DoEvents();Thread.Sleep(5);}Check(done(),"Game care UI task didn't finish");}
            int persisted=0;using var form=new GameCareForm(game,data,(care,args,path)=>{persisted++;Check(care.Notes=="Changed note"&&args=="-windowed"&&path==exe,"Wrong settings sent to persistence");});form.Show();Application.DoEvents();
            T Field<T>(string name)=>(T)typeof(GameCareForm).GetField(name,flags)!.GetValue(form)!;
            bool Busy()=>(bool)typeof(GameCareForm).GetField("busy",flags)!.GetValue(form)!;Pump(()=>!Busy());Check(Field<ModernSelect>("snapshots").Items.Count>0,"Snapshot UI empty");Field<ModernButton>("create").PerformClick();Pump(()=>!Busy()&&Field<ModernButton>("verify").Enabled);Field<ModernButton>("verify").PerformClick();Pump(()=>!Busy()&&Field<ModernButton>("verify").Enabled);Check(Field<Label>("status").Text.Contains("подтверждена"),"SHA verification result missing: "+Field<Label>("status").Text+"; index="+Field<ModernSelect>("snapshots").SelectedIndex+"; enabled="+Field<ModernButton>("verify").Enabled);
            IEnumerable<Control> Children(Control parent)=>parent.Controls.Cast<Control>().SelectMany(child=>new[]{child}.Concat(Children(child)));
            Children(form).OfType<ModernButton>().Single(b=>b.Text=="Запуск и заметки").PerformClick();Field<TextBox>("notes").Text="Changed note";Field<TextBox>("arguments").Text="-windowed";Children(form).OfType<ModernButton>().Single(b=>b.Text=="Сохранить настройки игры").PerformClick();Check(persisted==1,"Game settings weren't saved");
            form.Size=form.MinimumSize;Application.DoEvents();Check(Field<TextBox>("notes").Width>600,"Game care layout collapsed");form.Size=new Size(940,820);Application.DoEvents();Directory.CreateDirectory("artifacts");using(var screenshot=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(screenshot,form.ClientRectangle);screenshot.Save("artifacts/game-care-launch-preview.png");}
            Children(form).OfType<ModernButton>().Single(b=>b.Text=="Сохранения и копии").PerformClick();using(var screenshot=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(screenshot,form.ClientRectangle);screenshot.Save("artifacts/game-care-backups-preview.png");}
            using var confirm=new RestorePlanForm(store.Preview(first.Id),saves);confirm.Show();Application.DoEvents();Check(confirm.DialogResult!=DialogResult.OK,"Restore confirmed without user action");
            typeof(GameCareForm).GetMethod("ProcessCmdKey",flags)!.Invoke(form,new object[]{new Message(),Keys.Escape});Check(!form.Visible,"Escape didn't close game care");
        }
        Console.WriteLine($"PASS: {count} game-care checks: snapshots/SHA-256, preview/safety/rollback, cancellation/locking, unsafe paths/manifests, readiness/arguments, game mode and persistence"+(ui?", UI and explicit restore confirmation":"")+". Temporary fixtures only; no real games or saves changed.");
    }
}
